'use strict';
// sign 算法（纯 JS 实现 + 离线自校验）。
//
//   s1 = path + salt; d1 = md5(s1)
//   s2 = s1 + d1 + path; d2 = md5(s2)
//   s3 = s2 + d2 + T; d3 = md5(s3)
//   sign = md5(s3 + d3 + salt)
// salt = "wdi4n2t8edr"，path = URL 编码路径（不含 query）。
//
// T 是随分钟变化的设备常量，由 so 生成，线上计算走 native.calcSign（见 native.js）；
// 本文件只保存公式本身，并用固定样本 verifyWithFixture() 自证。

const crypto = require('node:crypto');

/** 硬编码 salt（so 内常量，勿改）。 */
const SALT = 'wdi4n2t8edr';

/** md5 → 32 位小写 hex。 */
function md5(input) {
  return crypto.createHash('md5').update(input, 'utf8').digest('hex');
}

/**
 * 按权威公式算 sign。
 *
 * @param {string} urlPath 只含路径（如 `/leo-game-pk/android/math/pk/submit`）
 * @param {string} T       设备时间派生串（从设备 so 取出，随分钟变化）
 * @param {string} [salt]  salt，默认 `wdi4n2t8edr`
 * @returns {string} 32 位小写 hex
 */
function chainMd5(urlPath, T, salt = SALT) {
  const p = String(urlPath);
  const s1 = p + salt;
  const d1 = md5(s1);
  const s2 = s1 + d1 + p;
  const d2 = md5(s2);
  const s3 = s2 + d2 + T;
  const d3 = md5(s3);
  return md5(s3 + d3 + salt);
}

/**
 * 离线自校验：用历史真机抓下来的固定样本验证公式。
 *
 * 样本来源：设备 so 的 dump 输出（`T=` 与 `SIGN=`），path 见下。
 * 这条样本曾在逆向阶段用于定位公式，留下它可防「后人把公式改坏」。
 *
 * @returns {{ok:boolean, expect:string, got:string}}
 */
/**
 * 离线自校验：用**真机抓包**里的固定样本验证公式 + T 生成。
 *
 * ## 样本版本：小猿 3.141.1（2026-10-08）
 *
 * ⚠️ 样本必须与 `bin/native/lre.so` 的版本对应：
 *   小猿 3.141.1 重编译了 `libRequestEncoder.so`（919600 → 919568 字节），
 *   T 函数地址平移（0x657b4 → 0x657a4）。
 *   若 so 与样本版本不一致，这里必然对不上 —— 那是**样本过期**，不是公式错。
 *   换版本时：用新版 so 重新生成指令表，再用该版本的真机日志反推新样本。
 *
 * 样本来源：真机 App 原生日志
 *   `/data/data/com.fenbi.android.leo/files/logs/auto_oral-2026-10-08.log`
 *
 * @returns {{ok:boolean, total:number, pass:number, fails:Array}}
 */
function verifyWithFixture() {
  const samples = [
    {
      path: "/leo-math/android/recommend/keypoint",
      T:
        "",
      sign: '44370c167e2c232e42ef630cb1b6a8ab',
    },
    {
      path: "/accounts/android/current",
      T:
        "",
      sign: '04e50f3dbf60cde503a5ef3b651549b4',
    },
    {
      path: "/tutor-app-version/android/app-versions/history/611",
      T:
        "",
      sign: '6f766072af730f5c15379acd58481bc9',
    },
    {
      path: "/leo-ai-chat/android/ai-companion/recommend",
      T:
        "",
      sign: '5ea4d2756088591698a2bf74fa3243e4',
    },
    {
      path: "/leo-english/android/textbook-version/list",
      T:
        "",
      sign: '45ccad3a91a47ce05489d9b36ef5a224',
    },
    {
      path: "/leo-ai-chat/android/ai-companion/recommend",
      T:
        "",
      sign: '5ea4d2756088591698a2bf74fa3243e4',
    },
  ];
  const fails = [];
  let pass = 0;
  for (const f of samples) {
    let got = null;
    try { got = chainMd5(f.path, f.T); } catch (e) { got = '异常:' + e.message; }
    if (got === f.sign) { pass++; }
    else { fails.push({ path: f.path, expect: f.sign, got: got }); }
  }
  return { ok: fails.length === 0, total: samples.length, pass: pass, fails: fails };
}

module.exports = { SALT, md5, chainMd5, verifyWithFixture };